}

// putAttributeValue stores an OpenTelemetry attribute value into a pcommon.Map,
// preserving the value's type.
func putAttributeValue(m pcommon.Map, key string, v attribute.Value) {
	switch v.Type() {
	case attribute.BOOL:
		m.PutBool(key, v.AsBool())
	case attribute.INT64:
		m.PutInt(key, v.AsInt64())
	case attribute.FLOAT64:
		m.PutDouble(key, v.AsFloat64())
	case attribute.STRING:
		m.PutStr(key, v.AsString())
	default:
		m.PutStr(key, v.Emit())
	}
}

// pcommonValueToAny converts a pcommon.Value into a plain Go value, preserving
// the underlying type so that it round-trips through the otelconf SDK.
func pcommonValueToAny(v pcommon.Value) any {
	switch v.Type() {
	case pcommon.ValueTypeBool:
		return v.Bool()
	case pcommon.ValueTypeInt:
		return v.Int()
	case pcommon.ValueTypeDouble:
		return v.Double()
	case pcommon.ValueTypeStr:
		return v.Str()
	default:
		return v.AsString()
	}
}
