func bi() component.BuildInfo {
	return component.BuildInfo{Command: "otelcol", Version: "latest"}
}

func TestScratchDefault(t *testing.T) {
	cfg := createDefaultConfig().(*Config)
	set := telemetry.Settings{BuildInfo: bi()}
	res, err := createResource(t.Context(), set, cfg)
	require.NoError(t, err)
	raw := res.Attributes().AsRaw()
	assert.Contains(t, raw, "service.instance.id")
	delete(raw, "service.instance.id")
	assert.Equal(t, map[string]any{"service.name": "otelcol", "service.version": "latest"}, raw)
}

func TestScratchLegacy(t *testing.T) {
	cfg := createDefaultConfig().(*Config)
	cm := confmap.NewFromStringMap(map[string]any{
		"extra.attr":          "value",
		"service.name":        "custom-service",
		"service.version":     "0.1.0",
		"service.instance.id": nil,
	})
	require.NoError(t, cfg.Resource.Unmarshal(cm))
	require.NotContains(t, cfg.Resource.LegacyAttributes, "service.instance.id")
	set := telemetry.Settings{BuildInfo: bi()}
	res, err := createResource(t.Context(), set, cfg)
	require.NoError(t, err)
	assert.Equal(t, map[string]any{
		"extra.attr":      "value",
		"service.name":    "custom-service",
		"service.version": "0.1.0",
	}, res.Attributes().AsRaw())
}

func TestScratchDeclarativeTypes(t *testing.T) {
	cfg := createDefaultConfig().(*Config)
	cfg.Resource.Attributes = []config.AttributeNameValue{
		{Name: "a.bool", Value: true},
		{Name: "a.int", Value: int(5)},
		{Name: "a.int64", Value: int64(7)},
		{Name: "a.uint8", Value: uint8(8)},
		{Name: "a.uint", Value: uint(200)},
		{Name: "a.uint64", Value: uint64(201)},
		{Name: "a.float32", Value: float32(1.5)},
		{Name: "a.float64", Value: float64(2.5)},
		{Name: "a.nil", Value: nil},
		{Name: "a.complex", Value: complex(1, 2)},
	}
	set := telemetry.Settings{BuildInfo: bi()}
	res, err := createResource(t.Context(), set, cfg)
	require.NoError(t, err)
	raw := res.Attributes().AsRaw()
	assert.Equal(t, true, raw["a.bool"])
	assert.Equal(t, int64(5), raw["a.int"])
	assert.Equal(t, int64(7), raw["a.int64"])
	assert.Equal(t, int64(8), raw["a.uint8"])
	assert.Equal(t, "200", raw["a.uint"])
	assert.Equal(t, "201", raw["a.uint64"])
	assert.Equal(t, 1.5, raw["a.float32"])
	assert.Equal(t, 2.5, raw["a.float64"])
	assert.Equal(t, "<nil>", raw["a.nil"])
	assert.Equal(t, "(1+2i)", raw["a.complex"])
}

func TestScratchValidate(t *testing.T) {
	// attributes_list unsupported
	list := "x"
	rc := migration.ResourceConfigV030{}
	rc.AttributesList = &list
	assert.ErrorContains(t, rc.Validate(), "resource::attributes_list is not currently supported")

	// attributes + legacy conflict
